# Articles supplémentaires de Wyattpédia : projets, lexique tech, jargon de dev.
from wiki_content import RN

def A(slug, cat, title, glyph, tone, short, box, lead, sections, see, refs=None, uses=None, alias=None):
    d = dict(slug=slug, cat=cat, title=title, glyph=glyph, tone=tone, short=short, box=box, lead=lead,
             sections=sections, see=see, refs=refs or ['Wyatt, avec une tasse de quelque chose, 2026.'])
    if uses: d['uses'] = uses
    if alias: d['alias'] = alias
    return d

P = lambda *xs: ''.join(f'<p>{x}</p>' for x in xs)

